import os
import google.generativeai as genai

class EmbeddingsClient:
    def __init__(self, api_key=None):
        self.api_key = api_key or os.environ.get("GOOGLE_API_KEY")
        if not self.api_key:
            raise ValueError("GOOGLE_API_KEY not found. Please set the environment variable or pass it to the client.")
        genai.configure(api_key=self.api_key)

    def get_client(self):
        return genai

import numpy as np
from scipy.spatial.distance import cosine
from typing import List, Dict

def similarity_score(payload: Dict) -> Dict:
    embedding1 = payload.get("embedding1")
    embedding2 = payload.get("embedding2")

    if not isinstance(embedding1, list) or not isinstance(embedding2, list):
        raise ValueError("Payload must contain 'embedding1' and 'embedding2' as lists of numbers.")

    if not embedding1 or not embedding2:
        raise ValueError("Embeddings cannot be empty.")

    # Convert lists to numpy arrays
    vec1 = np.array(embedding1)
    vec2 = np.array(embedding2)

    if vec1.shape != vec2.shape:
        raise ValueError("Embeddings must have the same dimensions.")

    # Compute cosine similarity. Note: scipy.spatial.distance.cosine returns distance, so 1 - distance is similarity.
    # Handle cases where vectors are zero to avoid NaN. Cosine similarity of zero vectors is undefined, 
    # but often treated as 0 or 1 depending on context. Here, if either is zero vector, similarity is 0.
    if np.all(vec1 == 0) or np.all(vec2 == 0):
        similarity = 0.0
    else:
        similarity = 1 - cosine(vec1, vec2)

    return {"similarity": float(similarity)}

import os
from typing import List, Dict
import google.generativeai as genai
from embeddings_models import GENAI_GENERATION_MODEL

def embedding_job_summary(payload: Dict, config: Dict = None) -> Dict:
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY not found. Please set the environment variable or pass it to the client.")

    genai.configure(api_key=api_key)
    model = genai.GenerativeModel(GENAI_GENERATION_MODEL)

    job_results = payload.get("job_results") # Expecting a list of dicts, each with 'text' and 'embedding'
    if not isinstance(job_results, list):
        raise ValueError("Payload must contain 'job_results' as a list.")

    if not job_results:
        return {"summary": "No embedding job results to summarize."}

    # Concatenate texts for summarization
    texts_to_summarize = [result.get("text", "") for result in job_results if result.get("text")]

    if not texts_to_summarize:
        return {"summary": "No texts found in job results to summarize."}

    combined_text = "\n---\n".join(texts_to_summarize[:5]) # Limit to first 5 texts for prompt length, adjust as needed
    if len(texts_to_summarize) > 5:
        combined_text += f"\n... and {len(texts_to_summarize) - 5} more items."

    prompt = f"Summarize the following texts that were part of an embedding job. Focus on the main topics and common themes:\n\n{combined_text}"

    try:
        response = model.generate_content(prompt)
        summary = response.text
    except Exception as e:
        summary = f"Error generating summary: {str(e)}"

    return {"summary": summary}

import os
from typing import List, Dict
import google.generativeai as genai
from embeddings_models import GENAI_GENERATION_MODEL

def corpus_safety(payload: Dict, config: Dict = None) -> Dict:
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY not found. Please set the environment variable or pass it to the client.")

    genai.configure(api_key=api_key)
    model = genai.GenerativeModel(GENAI_GENERATION_MODEL)

    texts_to_check = payload.get("texts", [])
    if not isinstance(texts_to_check, list) or not all(isinstance(t, str) for t in texts_to_check):
        raise ValueError("Payload must contain a 'texts' key with a list of strings.")

    safety_results = []
    for text in texts_to_check:
        try:
            # Generate content to implicitly trigger safety checks. The actual generated content is less important
            # than the safety feedback received in the response.
            response = model.generate_content(
                text,
                safety_settings=[
                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
                ]
            )
            # The prompt is sent, and the safety attributes are available in the response
            # if any blocking occurred or if specific attributes are present.
            # For this task, we want to report the safety feedback directly.
            safety_feedback = []
            if response._error:
                safety_feedback.append({"status": "ERROR", "message": str(response._error)})
            elif response.prompt_feedback and response.prompt_feedback.safety_ratings:
                for rating in response.prompt_feedback.safety_ratings:
                    safety_feedback.append({
                        "category": rating.category.name,
                        "probability": rating.probability.name,
                        "blocked": rating.blocked,
                    })
            else:
                safety_feedback.append({"status": "CLEAN", "message": "No explicit safety violations detected."})

            safety_results.append({"text": text, "safety_feedback": safety_feedback})

        except Exception as e:
            safety_results.append({"text": text, "safety_feedback": [{"status": "ERROR", "message": str(e)}]})

    return {"safety_checks": safety_results}
